'use strict';
// Shared by the approved catalog and training material selectors.
window.CatalogSelection={
 bindFilterReveal(content){if(!content)return;const bar=content.querySelector('.w-textbook-filterbar');if(!bar)return;const max=bar.offsetHeight;let last=content.scrollTop,offset=Math.min(max,Math.max(0,last));const fits=()=>content.scrollHeight<=content.clientHeight+1;const paint=value=>{offset=Math.max(0,Math.min(max,value));bar.style.transform=offset?`translateY(${-offset}px)`:'';bar.classList.toggle('is-concealed',offset>=max-.5);content.style.setProperty('--w-filter-stick',(max-offset)+'px');};paint(fits()?0:offset);content.addEventListener('scroll',()=>{const top=content.scrollTop,delta=top-last;last=top;if(fits()||top<=0){paint(0);return;}paint(offset+delta);},{passive:true});},

 wordRow(word,{gloss,html,aria,select=false,selected=false,interactive=true,footer=''}){const tag=interactive?'button':'div';return `<${tag}${interactive?' type="button"':''} class="n-word-row w-word-row w-dictionary-row${select?' w-dictionary-row--select':interactive?' w-dictionary-row--open':''}${[...word.written].length>8||[...word.reading].length>16?' is-long':''}" data-id="${word.id}"${interactive?` data-action="${select?'select-word':'word'}:${word.id}"`:''}${select?` data-material-word="${word.id}" aria-pressed="${selected}"`:''} aria-label="${html(aria||[word.written,word.reading,gloss].join('. '))}">${select&&selected?this.selectionMark():''}<span class="w-dictionary-japanese"><span class="n-word-written" lang="ja">${html(word.written)}</span><span class="n-word-reading" lang="ja">${html(word.reading)}</span></span><span class="n-word-translation">${html(gloss)}</span>${footer?`<span class="w-word-footer">${footer}</span>`:''}</${tag}>`;},

 filterValues(value){return [...new Set(Array.isArray(value)?value:value?[value]:[])];},
 filterMatches(value,item){const ids=this.filterValues(value);return !ids.length||ids.includes(item);},
 filterTitle(title,value,label=String){const ids=this.filterValues(value);if(!ids.length)return title;return title+' · '+ids.slice(0,2).map(label).join(', ')+(ids.length>2?' +'+(ids.length-2):'');},
 toggleFilter(value,id){const ids=this.filterValues(value);return ids.includes(id)?ids.filter(n=>n!==id):[...ids,id];},
 kanjiPicker({title,back,searchButton,content,apply}){return `<div class="kanji-picker-screen recipe-editor-screen material-catalog-filter"><header class="n-appbar">${back}<h2>${title}</h2>${searchButton}</header><div class="kanji-picker-content recipe-source-content n-content">${content}</div><div class="recipe-editor-footer kanji-picker-footer">${apply}</div></div>`;},
 wordDetails(word,{gloss,html,usage=null,usageTitle='',partsTitle='',kanjiTitle='',kanjiGrid='',footer=''}){const infoBlock=(title,body)=>`<section class="n-info-panel w-word-info"><h3>${html(title)}</h3>${body}</section>`;const longWord=[...word.written].length>6||[...word.reading].length>12;const identity=`<div class="n-word-hero w-word-identity${longWord?' is-long':''}"><span class="n-word-large ${[...word.written].length>8?'long':''}" lang="ja">${html(word.written)}</span><span class="w-word-detail-reading" lang="ja">${html(word.reading)}</span><p class="w-word-detail-translation">${html(gloss)}</p></div>`;const notes=usage?.usage_note?infoBlock(usageTitle,`<p class="w-usage-note" lang="${html(usage.language_tag)}">${html(usage.usage_note)}</p>`):'';const parts=word.parts?.length?infoBlock(partsTitle,word.parts.map(p=>`<p class="w-word-reading-part"><span lang="ja">${html(p.written_part)}</span><span lang="ja">${html(p.reading_part)}</span></p>`).join('')):'';const kanji=kanjiGrid?`<section class="n-section"><h3>${html(kanjiTitle)}</h3><div class="w-word-kanji-grid">${kanjiGrid}</div></section>`:'';return `<div class="n-detail w-word-detail">${identity}${notes}${parts}${kanji}${footer}</div>`;},
 selectionMark(){return '<span class="w-choice-check" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 4 4L19 6"/></svg></span>';}, 
 symbolGrid(items,o){
  const {radicals=false,select=false,showPlacement=true,sourceId,selectedIds=[],placementByKey,uiLanguage,text,plural,meaning,radicalName,meaningVariants,html}=o;
  const ru=uiLanguage()==='ru';
  return `<div class="${radicals?'n-radical-grid':'n-kanji-grid'} w-compact-grid">${items.map(item=>{
   const placement=showPlacement&&!radicals&&sourceId?placementByKey.get(sourceId+':'+item.id):null;
   const number=radicals?item.id:placement?.kanji_number,chapter=placement?.chapter_number;
   const ordinal=chapter&&number?chapter+'–'+number:number;
   const full=radicals?radicalName(item):meaning(item);
   const variants=radicals?[full]:meaningVariants(item);
   const strokesLabel=!radicals&&!select&&item.stroke_count?plural('catalog_strokes',item.stroke_count):'';
   const label=(chapter?text('catalog_chapter',chapter)+'. ':'')+(number?(radicals?text('catalog_radical_number',number):(ru?'Кандзи № ':'Kanji no. ')+number)+'. ':'')+(strokesLabel?strokesLabel+'. ':'')+item.symbol+' · '+full;
   const selected=select&&selectedIds.includes(item.id);
   const mark=selected?this.selectionMark():'';
   const target=radicals?'radical':'kanji';
   return `<button type="button" class="${radicals?'n-radical-tile':'n-kanji-tile'} w-numbered-kanji w-compact-symbol${radicals?' w-full-caption':''}" data-id="${item.id}"${radicals?` data-stroke-tone="${(Math.max(1,item.stroke_count)-1)%4}"`:''} data-action="${select?'select-'+target:target}:${item.id}" aria-label="${html(label)}"${select?` aria-pressed="${selected}"`:''}>${number?`<span class="w-kanji-ordinal" aria-hidden="true">${html(ordinal)}</span>`:''}${mark}<span class="${radicals?'n-radical-symbol':'n-kanji-symbol'}" lang="ja" aria-hidden="true">${html(item.symbol)}</span><span class="w-kanji-caption-slot" aria-hidden="true"><span class="n-kanji-meaning" data-meaning-variants="${html(JSON.stringify(variants))}">${html(full)}</span></span>${strokesLabel?`<span class="w-kanji-strokes">${html(strokesLabel)}</span>`:''}</button>`;
  }).join('')}</div>`;
 },
 navRow({title,subtitle,target,label=title,html,chevron='',select=false,selected=false}){return `<button type="button" class="n-nav-row w-nav-row${select?' w-nav-row--select':''}" data-action="${target}"${select?` aria-pressed="${selected}"`:''} aria-label="${html(label)}"><span><strong>${html(title)}</strong>${subtitle!==null&&subtitle!==undefined?`<small>${html(subtitle)}</small>`:''}</span>${select?(selected?CatalogSelection.selectionMark():''):chevron}</button>`;},
 chapterCard({number,label,counts,preview,select=false,selected=false,html}){const chevron='<svg class="p-book-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg>';return `<button type="button" class="n-chapter-card p-book-chapter-card${select?' p-chapter-choice':''}" data-id="${number}" data-action="${select?'select-chapter':'chapter'}:${number}" ${select?`aria-pressed="${selected}"`:''} aria-label="${html(label+'. '+counts)}"><span class="p-book-card-heading"><span class="p-book-card-labels"><strong>${html(label)}</strong><small>${html(counts)}</small></span>${select&&selected?this.selectionMark():chevron}</span><span class="p-book-chapter-preview" aria-hidden="true">${preview}</span></button>`;},
 filterChip({title,type,active=false,clear,clearLabel,arrow,close,html,disabled=false}){return `<span class="w-textbook-chip${active?' is-active':''}" role="group" aria-label="${html(title)}"><button type="button" class="w-chip-open" data-action="filter:${type}"${disabled?' disabled':''}><span>${html(title)}</span>${active?'':arrow}</button>${active?`<button type="button" class="w-chip-reset" data-action="${clear}" aria-label="${html(clearLabel)}">${close}</button>`:''}</span>`;}
};
